assignments.value:
={{ (() => {
  const p = $json.body.payload || {};
  const info = p._data?.Info || {};
  const from = String(p.from || "");
  const chat = String(info.Chat || "");
  const senderAlt = String(info.SenderAlt || p.participant || "");
  const normalize = (jid) => {
    let x = String(jid || "");
    if (!x) return "";
    x = x.replace(/:\d+(?=@s\.whatsapp\.net)/, "");
    if (x.includes("@s.whatsapp.net")) return x.replace("@s.whatsapp.net", "@c.us");
    if (x.includes("@c.us")) return x;
    return x;
  };
  const isGroup = !!info.IsGroup || from.includes("@g.us") || chat.includes("@g.us");
  const isStatus = from.includes("status@broadcast") || from.includes("@broadcast") || chat.includes("status@broadcast");
  const isNewsletter = from.includes("@newsletter") || chat.includes("@newsletter");
  if (isGroup || isStatus || isNewsletter) return "";
  if (from.includes("@c.us")) return from;
  if (from.includes("@s.whatsapp.net")) return normalize(from);
  if (from.includes("@lid") && senderAlt) return normalize(senderAlt);
  if (chat.includes("@c.us")) return chat;
  if (chat.includes("@s.whatsapp.net")) return normalize(chat);
  if (chat.includes("@lid") && senderAlt) return normalize(senderAlt);
  return normalize(from || chat);
})() }}

parameters.text:
={{ (() => {
  const saida = $('AI Agent').item.json.output || $('AI Agent').item.json.text || $('AI Agent').item.json.message || '';
  const nome = $('Edit Fields').item.json.pushName || 'Não informado';

  const linhas = saida.split('\n').map(l => l.trim()).filter(Boolean);

  const pegaCampo = (rotulo) => {
    const linha = linhas.find(l => l.toLowerCase().includes(rotulo.toLowerCase()));
    if (!linha) return '';
    return linha.replace(/^.*?:\s*/, '').trim();
  };

  let dia = pegaCampo('Dia');
  let horario = pegaCampo('Horário') || pegaCampo('Horario');

  // Segurança: se a IA tentar mandar placeholder, não repassa para o grupo
  const invalido = (v) => !v || v.includes('[') || v.includes(']') || v.toLowerCase().includes('dia da semana') || v.toLowerCase().includes('dia-da-semana') || v.toLowerCase().includes('horário') && v.includes('[');

  if (invalido(dia)) dia = 'Verificar no atendimento';
  if (invalido(horario)) horario = 'Verificar no atendimento';

  return (
    '🥊 NOVA AULA EXPERIMENTAL CONFIRMADA\n\n' +
    '👤 Contato: ' + nome + '\n\n' +
    '📆 Dia: ' + dia + '\n' +
    '🕒 Horário: ' + horario + '\n\n' +
    '⚠️ Confirmado automaticamente pelo bot.'
  );
})() }}
